        outcome = "draft_missing"
    else:
        slug = str(draft.get("slug") or "")
        practice = read_json("PracticeManager/Practices/" + slug + ".json", {}) or {}
        tz = practice_tz(practice)
        decision = str(responses.get("q_decision") or "")
        other_id = re.sub(r"\D", "", str(responses.get("q_patient_id") or ""))
        name = str(draft.get("name") or "the attachment")

        if decision == "Don't file":
            api.workq.comment(todo_id=todo_id, body="Marked as don't file. Nothing was added to Cliniko.")
            api.workq.complete(todo_id=todo_id)
            audit(slug, tz, SOURCE, "rejected", {"kind": "email_attachment", "id": str(draft.get("message_id") or "")},
                  "Reviewer chose not to file '" + name + "'", todo_id)
            delete_file(draft_path)
            outcome = "not_filed"
        else:
            patient_id = other_id if decision == "File on the patient ID below" else str(draft.get("suggested_patient_id") or "")
            patient = {}
            if patient_id:
                try:
                    patient = api.connectors.invoke(server="cliniko-patients", tool="get_patient", args={"id": patient_id}) or {}
                except Exception:
                    patient = {}
            if not patient_id or not patient.get("id"):
                api.workq.comment(
                    todo_id=todo_id,
                    body=("No suggested patient on this item - choose \"File on the patient ID below\" and enter the Cliniko patient ID."
                          if decision != "File on the patient ID below" and not patient_id
                          else "Couldn't find Cliniko patient " + (patient_id or "(blank)") + ". Check the ID and submit the form again.")
                    + " Nothing was filed.",
                )
                outcome = "patient_not_found"
            else:
                try:
                    att = fetch_attachment(str(draft.get("message_id") or ""), str(draft.get("attachment_id") or ""))
                    res = file_document(patient_id, att, draft.get("extracted") or {}, str(draft.get("received") or ""))
                    error = ""
                except Exception as exc:
                    res = {}
                    error = str(exc)[:300]
                if error:
                    api.workq.comment(todo_id=todo_id, body="Filing failed, so nothing was added: " + error + "\n\nSubmit the form again to retry, or file it by hand in Cliniko.")
                    outcome = "filing_failed"
                else:
                    label = patient_name(patient)
                    audit(slug, tz, SOURCE, "approved", {"kind": "patient_attachment", "id": str(res.get("attachment_id") or "")},
                          "Filed '" + name + "' on " + label + " after a person confirmed the patient", todo_id)
                    api.workq.comment(todo_id=todo_id, body="\n".join(summary_lines(res, label)))
                    api.workq.complete(todo_id=todo_id)
                    kind = str((draft.get("extracted") or {}).get("document_type") or "")
                    reviewer = practice.get("reviewer_id") or ""
                    if reviewer and kind in ("result", "imaging"):
                        api.notify.send(title=str(res.get("label") or "Document") + " filed for " + label,
                                        body="Ready to review in Cliniko: " + name, user_ids=[str(reviewer)])
                    delete_file(draft_path)
                    outcome = "filed"
